  A.modal({ title: `Publish ${r.version} to production`, subtitle: `${p.name} · ${p.envs.prod} · currently ${p.envs.prodVersion}`, width: 540, checks: [check(true, `${r.taskIds.length} task(s) · all QA passed${r.uatRequired ? ' · UAT approved' : ''}`), check(true, 'Approvals complete: ' + Object.values(r.approvals).filter(Boolean).map(a => A.name(a.by)).join(' · ')), check(true, `Tag ${r.version} · checks passed`), check(true, 'You are an authorized publisher for this project')], notes: [note(`1 · GitHub workflow deploy-production.yml runs with ref ${r.version}  ·  2 · Deployment result recorded  ·  3 · Live-verification assignment created for ${A.name(p.testerId)}  ·  4 · Clients see "Published live"; tasks complete only after verification  ·  5 · Rollback target ${r.rollback}`)], fields: [{ key: 'when', type: 'seg', label: 'When', options: [{ value: 'now', label: 'Now' }, { value: 'sched', label: `Scheduled ${r.planned}` }], value: 'now' }, { key: 'confirm', type: 'text', label: 'Type the version to confirm', placeholder: r.version }], footer: 'Recorded in the audit log with your name, time and IP.', actions: [{ label: 'Cancel', kind: 'secondary', onClick: () => A.closeModal() }, { label: 'Publish to production', kind: 'dark', onClick: () => { if ((A.val('confirm') || '').trim() !== r.version) return A.toast(`Type ${r.version} to confirm`); if (A.val('when') === 'sched') { r.status = 'SCHEDULED'; A.audit('RELEASE', `${r.version} scheduled for ${r.planned}`); A.save(); A.closeModal(); return A.toast(`Scheduled for ${r.planned}`); } r.status = 'PUBLISHED'; r.publishedAt = '04/09 ' + A.tick(); r.publishedBy = A.me.id; p.envs.prodVersion = r.version.replace('v', ''); A.audit('RELEASE', `Published ${r.version} to production`); A.audit('DEPLOY', `Production deployment success · ${r.version} · ${p.repo}`); const q = { id: 'LV-' + (A.D.counter.qa++), taskId: r.taskIds[0], releaseId: r.id, kind: 'LIVE', testerId: p.testerId, status: 'PENDING', deadline: 'in 2h', env: 'Production', whatToTest: 'Smoke test: ' + r.taskIds.map(id => A.T(id).title).join(', '), devNotes: '', browsers: 'Chrome', account: 'Test Customer (prod)', grant: { expires: 'in 2h', revealed: false }, result: null }; A.D.qa.unshift(q); r.taskIds.forEach(id => { const t = A.T(id); if (t.status === 'READY_TO_PUBLISH') A.transition(t, 'PUBLISHED_LIVE', r.version); }); A.notify(p.testerId, `Live verification ${q.id} for ${r.version} — due in 2h`, 'qaDetail', q.id); A.save(); A.closeModal(); A.toast(`${r.version} published — live verification assigned to ${A.name(p.testerId)}`); } }] });
