export function rollback(A, relId) { const r = A.R(relId); const p = A.P(r.projectId); A.modal({ title: `Roll back to ${r.rollback}`, subtitle: `${r.version} · ${p.envs.prod}`, width: 480, notes: [note('Rollback redeploys the previous tag and reopens live verification. Clients keep seeing "In development".', 'danger')], fields: [{ key: 'reason', type: 'area', label: 'Reason', full: true }], actions: [{ label: 'Cancel', kind: 'secondary', onClick: () => A.closeModal() }, { label: 'Roll back now', kind: 'danger', onClick: () => { r.status = 'ROLLED_BACK'; p.envs.prodVersion = r.rollback.replace('v', ''); A.audit('RELEASE', `${r.version} rolled back to ${r.rollback} — ${A.val('reason') || ''}`); r.taskIds.forEach(id => { const t = A.T(id); if (['LIVE_FAILED', 'ROLLBACK_REQUIRED', 'LIVE_VERIFICATION', 'PUBLISHED_LIVE'].includes(t.status)) { t.status = 'RETURNED_TO_DEV'; t.history.push({ from: 'ROLLBACK_REQUIRED', to: 'RETURNED_TO_DEV', by: A.me.id, at: '04/09 ' + A.now(), note: 'Rolled back' }); } }); A.save(); A.closeModal(); A.toast(`Rolled back to ${r.rollback}`); } }] }); }
export function requestApproval(A, relId) { const r = A.R(relId); const p = A.P(r.projectId); r.status = 'APPROVAL_REQUESTED'; p.approvers.forEach(k => { const uid = ({ senior: p.seniorId, pm: 'u_anita', qa: p.testerId, client: (A.D.users.find(u => u.orgId === p.orgId && u.role === 'clientadmin') || {}).id, director: 'u_rahul' })[k]; if (uid && k !== 'client') { A.addMgmtTask(`Approve release ${r.version}`, 'Release Approval', uid, p.id, null).toString(); A.D.tasks[0].releaseId = r.id; A.notify(uid, `Release ${r.version} needs your approval`, 'releaseDetail', r.id); } }); if (r.uatRequired && !A.D.uat.find(u => u.releaseId === r.id)) { const u = { id: 'UAT-' + (A.D.counter.uat++), releaseId: r.id, taskIds: r.taskIds.slice(), orgId: p.orgId, status: 'PENDING', title: `Please try the changes in ${r.version}`, summary: r.taskIds.map(id => A.T(id).clientUpdate || A.T(id).title), checklist: r.taskIds.flatMap(id => A.T(id).acceptance.slice(0, 1)), respondBy: r.planned, requestedBy: A.me.id, preview: p.envs.staging, decidedBy: null, note: '' }; A.D.uat.unshift(u); const ca = A.D.users.find(x => x.orgId === p.orgId && x.role === 'clientadmin'); if (ca) A.notify(ca.id, `Release ${r.version} is ready for your approval`, 'portalApprovals', u.id); } A.audit('RELEASE', `${r.version} approval requested`); A.save(); A.toast('Approval tasks created for approvers'); }

export function uatDecision(A, uatId, decision) {
  const u = A.UAT(uatId);
  A.modal({ title: decision === 'approve' ? 'Approve — go ahead and release' : 'Request changes', subtitle: u.title, width: 480, fields: [{ key: 'note', type: 'area', label: decision === 'approve' ? 'Comment (optional)' : 'What should change? (required)', full: true }], footer: decision === 'approve' ? 'The team can now publish this to your live system.' : 'The work returns to the team and the release is held.', actions: [{ label: 'Cancel', kind: 'secondary', onClick: () => A.closeModal() }, { label: decision === 'approve' ? 'Approve' : 'Request changes', kind: decision === 'approve' ? 'good' : 'danger', onClick: () => { const n = (A.val('note') || '').trim(); if (decision !== 'approve' && !n) return A.toast('Tell us what should change'); u.status = decision === 'approve' ? 'APPROVED' : 'CHANGES_REQUESTED'; u.decidedBy = A.me.id; u.note = n; u.decidedAt = '04/09 ' + A.now(); u.taskIds.forEach(id => { const t = A.T(id); if (!t) return; if (decision === 'approve') { if (t.status === 'CLIENT_UAT') A.transition(t, 'READY_TO_PUBLISH', 'Client approved UAT', A.me.id); } else { t.comments.push({ by: A.me.id, at: '04/09 ' + A.now(), body: 'Client requested changes: ' + n, pub: true }); if (['CLIENT_UAT', 'READY_TO_PUBLISH', 'QA_PASSED'].includes(t.status)) A.transition(t, 'RETURNED_TO_DEV', 'Client requested changes: ' + n, A.me.id); } }); if (u.releaseId) { const r = A.R(u.releaseId); r.uatStatus = u.status; if (decision === 'approve') { if (r.approvals.client !== undefined) r.approvals.client = { by: A.me.id, at: '04/09 ' + A.now() }; if (Object.values(r.approvals).every(Boolean)) r.status = 'APPROVED'; } else r.status = 'DRAFT'; } A.audit('UAT', `${u.id} ${u.status} by ${A.me.name}`); A.notify(u.requestedBy, `Client ${decision === 'approve' ? 'approved' : 'requested changes on'} ${u.id}${n ? ': ' + n : ''}`, 'releaseDetail', u.releaseId); A.save(); A.closeModal(); A.toast(decision === 'approve' ? 'Thank you — approved' : 'Sent to the team'); } }] });
}
export function uatComment(A, uatId) { const u = A.UAT(uatId); A.modal({ title: 'Add a comment', subtitle: u.title, width: 440, fields: [{ key: 'c', type: 'area', label: 'Comment', full: true }], actions: [{ label: 'Cancel', kind: 'secondary', onClick: () => A.closeModal() }, { label: 'Send', kind: 'primary', onClick: () => { const c = (A.val('c') || '').trim(); if (!c) return A.toast('Type a comment'); u.comments = (u.comments || []).concat({ by: A.me.id, at: '04/09 ' + A.now(), body: c }); A.notify(u.requestedBy, `Client comment on ${u.id}: ${c}`, 'releaseDetail', u.releaseId); A.save(); A.closeModal(); A.toast('Comment sent'); } }] }); }

export function exportModal(A, what) { A.modal({ title: `Export ${what}`, width: 420, fields: [{ key: 'fmt', type: 'seg', label: 'Format', options: [{ value: 'pdf', label: 'PDF' }, { value: 'csv', label: 'CSV' }, { value: 'xlsx', label: 'Excel' }], value: 'pdf' }, { key: 'range', type: 'select', label: 'Range', options: ['Today', 'This week', 'This month', 'Custom…'].map(v => ({ value: v, label: v })), value: 'Today' }], actions: [{ label: 'Cancel', kind: 'secondary', onClick: () => A.closeModal() }, { label: 'Download', kind: 'primary', onClick: () => { A.audit('EXPORT', `${what} exported as ${A.val('fmt').toUpperCase()}`); A.save(); A.closeModal(); A.toast(`${what}.${A.val('fmt')} downloaded (prototype)`); } }] }); }
export function notifPrefs(A) { A.modal({ title: 'Notification preferences', subtitle: 'Per event · in-app is always on', width: 560, fields: ['New task', 'Due date / overdue', 'Review request', 'Rejected review', 'New ticket / reply', 'SLA risk', 'Client approval', 'QA result', 'Release published', 'Contract expiry'].map((e, i) => ({ key: 'p' + i, type: 'select', label: e, options: ['In-app only', 'In-app + email', 'In-app + email + WhatsApp', 'Daily digest'].map(v => ({ value: v, label: v })), value: i % 3 === 0 ? 'In-app + email' : 'In-app only' })), footer: 'Passwords and internal details are never included in email or WhatsApp.', actions: [{ label: 'Cancel', kind: 'secondary', onClick: () => A.closeModal() }, { label: 'Save preferences', kind: 'primary', onClick: () => { A.closeModal(); A.toast('Preferences saved'); } }] }); }
export function commentModal(A, taskId) { const t = A.T(taskId); A.modal({ title: 'Add comment', subtitle: `${t.id} · ${t.title}`, width: 480, fields: [{ key: 'body', type: 'area', label: 'Comment', full: true }, { key: 'pub', type: 'toggle', label: 'Visibility', toggleLabel: 'Client-visible (default internal)', value: false }], actions: [{ label: 'Cancel', kind: 'secondary', onClick: () => A.closeModal() }, { label: 'Post', kind: 'primary', onClick: () => { const b = (A.val('body') || '').trim(); if (!b) return A.toast('Type a comment'); t.comments.push({ by: A.me.id, at: '04/09 ' + A.now(), body: b, pub: !!A.val('pub') }); A.save(); A.closeModal(); A.toast('Comment added'); } }] }); }
export function editEntity(A, title, fields, onSave) { A.modal({ title, width: 520, fields, actions: [{ label: 'Cancel', kind: 'secondary', onClick: () => A.closeModal() }, { label: 'Save', kind: 'primary', onClick: () => { onSave(k => A.val(k)); A.save(); A.closeModal(); A.toast('Saved'); } }] }); }
export function guide(A) { A.modal({ title: 'Test-flow guide', subtitle: 'Follow these steps, switching role in the black bar as you go', width: 640, lines: [
  ['Senior Developer', 'Tasks → + Create Task → "Create and assign" to Priya S.'],
  ['Developer (Priya)', 'Open the task → Start Work → Development completed → Open PR & request review.'],
  ['Senior Developer', 'Notifications → open the task → Approve (checks pass → deployed to staging, Ready for QA).'],
  ['Developer', 'Task → Send for testing (tester Kavya, test account auto-selected).'],
  ['Tester / QA', 'QA dashboard → open assignment → Reveal credentials → Pass (or Fail and return, then Developer: Submit fix → Retest).'],
  ['Client Admin (if Acme CRM)', 'Approvals → Approve. Task becomes Ready to publish.'],
  ['Project Manager', 'Releases → open release → Add task → Request approval → approve as roles → Publish to production (type the version).'],
  ['Tester / QA', 'Live verification assignment → Verified — tasks complete, linked tickets resolve.'],
  ['Client Employee', 'Tickets → open the ticket → Close (or Reopen).'],
  ['— Support routing —', 'Client Admin: Raise ticket type Bug/Performance → routed straight to the module developer (Arjun on leave → skipped).'],
  ['Senior', 'Support → SLA dashboard → Advance clock +15 min → ticket escalates to backup, then senior.'],
  ['Support / Senior', 'Ticket → Link duplicate / Problem; 3 clients → Problem auto-created → Problem detail → Request RCA → Developer: Submit RCA.'],
  ['Developer', 'Support queue → Simulate incoming IVR call → Accept → wrap-up; or Mark no answer → callback task. Then Start work → review → staging → QA → release → live smoke → ticket Resolved.'],
].map(([r, s], i) => ({ text: `${i + 1} · ${r}: ${s}`, style: 'display:flex;gap:8px;padding:6px 0;border-bottom:1px solid #efefec;font-size:12.5px;color:#4a4b4e' })), actions: [{ label: 'Got it', kind: 'primary', onClick: () => A.closeModal() }] }); }
